package com.acme.inventory;

import org.junit.jupiter.api.Test;

import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

class OrderEventListenerContractTest {

    @Test
    void toleratesProducerAddedLoyaltyTierField() throws Exception {
        ReservationService reservations = mock(ReservationService.class);
        OrderEventListener listener = new OrderEventListener(reservations);
        String payload = "{\"orderId\":\"ord_99200\",\"customerId\":\"cust_7\","
                + "\"lines\":[{\"sku\":\"SKU-1\",\"quantity\":1}],"
                + "\"placedAt\":\"2026-11-01T15:32:00Z\",\"channel\":\"WEB\","
                + "\"loyaltyTier\":\"GOLD\"}";

        listener.onOrderPlaced(payload);

        verify(reservations).reserve(eq("ord_99200"), anyList());
    }
}

